import os
from pathlib import Path
# Check process environments for presence of the exact variable name without printing values.
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit(): continue
 try:
  data=(proc/'environ').read_bytes()
  names=[x.split(b'=',1)[0].decode('ascii','replace') for x in data.split(b'\0') if b'=' in x]
  if 'SHOPIFY_API_SECRET' in names or any('SHOPIFY' in n.upper() for n in names):
   print('pid',proc.name,'relevant names',[n for n in names if 'SHOPIFY' in n.upper()])
 except (PermissionError, ProcessLookupError, FileNotFoundError): pass
# Search plausible small config/code trees for exact variable name.
roots=['/work','/inputs','/opt','/srv','/root','/home','/run','/tmp']
found=[]
for root in roots:
 for dp,dns,fns in os.walk(root):
  dns[:] = [d for d in dns if d not in {'.git','node_modules','__pycache__'}]
  for fn in fns:
   p=Path(dp)/fn
   try:
    if p.stat().st_size <= 2_000_000 and b'SHOPIFY_API_SECRET' in p.read_bytes(): found.append(str(p))
   except (OSError, PermissionError): pass
print('files containing variable name:',found)
